/// <summary>
/// Data Entity for AssetTrans
/// </summary>
public class AVAFASAssetTransEntity extends common
{
}

Method.Source:
/// <summary>
/// Validates the records
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean isValid = AVAFASAssetTransEntity::validateAssetTrans(this);

    if (isValid)
    {
        isValid = super();
    }

    return isValid;
}

/// <summary>
/// Necessary validations and related error messages
/// </summary>
/// <param name = "_assetTransEntity">Current Entity</param>
/// <returns>Result of validations</returns>
public static boolean validateAssetTrans(AVAFASAssetTransEntity _assetTransEntity)
{
    boolean     isValid = true;
    AssetTable  assetTable = AssetTable::find(_assetTransEntity.AssetId);
    AssetBook   assetBook = AssetBook::find(_assetTransEntity.AssetId, _assetTransEntity.BookId);

    if(!assetTable)
    {
        isValid = checkFailed("@NDX:NXAErrorMessageAssetTransEntityAssetValidation");
    }

    if(assetTable && !assetBook)
    {
        isValid = checkFailed("@NDX:NXAErrorMessageAssetTransEntityBookValidation");
    }

    return isValid;
}

/// <summary>
/// Creates or updates all records at the same time
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">Current DMFDefinitionGroupExecution</param>
/// <returns>Container of created and updated records</returns>
public static container copyCustomStagingToTarget(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    // clear out any validation errors from previous runs.
    DMFStagingValidationLog log;
    log.skipDataMethods(true);

    delete_from log
        where log.DefinitionGroupName == _dmfDefinitionGroupExecution.DefinitionGroup
           && log.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId;

    AVAFASAssetTransStaging staging;

    // Set all Validated records back to NotStarted so they will be attempted again.
    update_recordset staging setting TransferStatus = DMFTransferStatus::NotStarted
        where staging.TransferStatus == DMFTransferStatus::Validated
            && staging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
            && staging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId;

    // Get the number of records updated.
    int64 updatedRecords = AVAFASAssetTransEntity::updateExistingAssetTrans(_dmfDefinitionGroupExecution);

    // Get the number of records inserted.
    int64 newRecords = AVAFASAssetTransEntity::createAssetTrans(_dmfDefinitionGroupExecution);
    return [newRecords, updatedRecords];
}

/// <summary>
/// Updates all records at the same time
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">Current DMFDefinitionGroupExecution</param>
/// <returns>Number of updated records</returns>
protected static int64 updateExistingAssetTrans(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    AssetTrans assetTrans;
    assetTrans.skipDataMethods(true);
    AVAFASAssetTransStaging staging;

    update_recordset assetTrans setting
            AmountCur = staging.AmountCur,
            AmountMST = staging.AmountMST,
            Txt = staging.Txt,
            AssetGroup = staging.AssetGroup,
            AssetId = staging.AssetId,
            BookId = staging.BookId,
            CurrencyCode = staging.CurrencyCode,
            DefaultDimension = staging.DefaultDimension,
            DisposalTransaction = staging.DisposalTransaction,
            PostingProfile = staging.PostingProfile,
            Reclassification = staging.Reclassification,
            TransDate = staging.TransDate,
            TransType = staging.TransType,
            Voucher = staging.Voucher
        join staging
            where staging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                && staging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
                && staging.AssetGroup == assetTrans.AssetGroup
                && staging.AssetId == assetTrans.AssetId
                && staging.BookId == assetTrans.BookId
                && staging.TransDate == assetTrans.TransDate
                && staging.TransType == assetTrans.TransType
                && staging.Voucher == assetTrans.Voucher
                && staging.Txt == assetTrans.Txt;

    return assetTrans.RowCount();
}

/// <summary>
/// Creates all records at the same time
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">Current DMFDefinitionGroupExecution</param>
/// <returns>Number of created records</returns>
protected static int64 createAssetTrans(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    AssetTrans assetTrans;
    assetTrans.skipDataMethods(true);
    AVAFASAssetTransStaging staging;
    SelectableDataArea currentCompany = curExt();

    insert_recordset assetTrans 
        (
        AmountCur, AmountMST, Txt, AssetGroup, AssetId,
        BookId, CurrencyCode,
        DefaultDimension,
        DisposalTransaction,
        PostingProfile, Reclassification,
        TransDate, TransType, Voucher
        )
    select
        AmountCur, AmountMST, Txt, AssetGroup, AssetId,
        BookId, CurrencyCode,
        DefaultDimension,
        DisposalTransaction,
        PostingProfile, Reclassification,
        TransDate, TransType, Voucher
    from staging
        where staging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
            && staging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
            && staging.TransferStatus == DMFTransferStatus::NotStarted;

    return assetTrans.RowCount();
}

